; xorshift.asm -- chapter 41: a 16-bit xorshift
; generated by gen41.py
        INCLUDE "msx.inc"
        OUTPUT "xorshift.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; xorshift.asm: a 16-bit xorshift from 1, its whole period of 65,535,
; each high byte plotted against the one before.
seed    EQU VARS                ; random's state, two bytes
seed8   EQU VARS + 2            ; lcg's
num     EQU VARS + 3            ; strips: the number, and the bits left
left    EQU VARS + 4
counts  EQU $C400               ; rows.asm: 3 x 24 counts of two bytes
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VDP_REG 1, $C0          ; display on: the plotting is watched
        ld hl, 1
        ld (seed), hl           ; the seed, 1
        ld b, 0                 ; B: the number before, the seed's high byte
        ld hl, 65535
xs1:    push hl
        call random             ; A: the next
        ld c, a
        cp 192
        jr nc, xs2              ; below the paper: not plotted
        call plot
xs2:    ld b, c
        pop hl
        dec hl
        ld a, h
        or l
        jr nz, xs1
done:   jr done

; random: the next of the 65,535 states of a 16-bit xorshift, x XOR x << 7,
; XOR x >> 9, XOR x << 8 -> seed, A = its high byte. Uses A, HL
random: ld hl, (seed)           ; 17
        ld a, h                 ;  5
        rra                     ;  5  bit 0 of H into the carry
        ld a, l                 ;  5
        rra                     ;  5  x << 7's high byte: that bit and L >> 1
        xor h                   ;  5
        ld h, a                 ;  5  H XOR it
        ld a, l                 ;  5
        rrca                    ;  5
        and $80                 ;  8  x << 7's low byte: L's bit 0 at bit 7
        xor l                   ;  5
        ld l, a                 ;  5  x XOR x << 7
        ld a, h                 ;  5
        srl a                   ; 10  x >> 9, which is H >> 1
        xor l                   ;  5
        ld l, a                 ;  5  x XOR x >> 9, which changes L alone
        xor h                   ;  5
        ld h, a                 ;  5  x XOR x << 8: H XOR L
        ld (seed), hl           ; 17
        ret                     ; 11

; vaddr: B = x, C = y -> HL = the address of the byte that holds pixel (x, y),
; in the patterns of a Graphic II screen whose names run 0 to 255 in each
; third (chapter 22). Uses A.
vaddr:  ld a, c                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $1F                 ;  8: y / 8, the row of characters
        ld h, a                 ;  5
        ld a, b                 ;  5
        and $F8                 ;  8: the column of characters, x 8
        ld l, a                 ;  5
        ld a, c                 ;  5
        and 7                   ;  8: the line in the cell
        or l                    ;  5
        ld l, a                 ;  5
        ret                     ; 11

; plot: B = x, C = y: pixel (x, y) set, the other seven of its byte kept:
; the byte read, changed and written back. Uses A, DE, HL.
plot:   call vaddr              ; 18  HL: the byte
        ld a, l                 ;  5
        out (VDP_CTRL), a       ; 12  the read address
        ld a, h                 ;  5
        out (VDP_CTRL), a       ; 12  ... and the VDP reads the byte ahead
        ld d, high masks        ;  8  while it reads, the pixel's mask
        ld a, b                 ;  5
        and 7                   ;  8
        ld e, a                 ;  5
        ld a, (de)              ;  8
        ld e, a                 ;  5  E: $80 >> (x AND 7)
        in a, (VDP_DATA)        ; 12  the byte
        or e                    ;  5  and the pixel
        ld e, a                 ;  5
        ld a, l                 ;  5
        out (VDP_CTRL), a       ; 12  the write address
        ld a, h                 ;  5
        or $40                  ;  8
        out (VDP_CTRL), a       ; 12
        ld a, e                 ;  5
        out (VDP_DATA), a       ; 12  the byte, with the pixel
        ret                     ; 11

        ALIGN 256
masks:  db $80, $40, $20, $10, $08, $04, $02, $01   ; pixel n of a byte: bit 7 - n
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
